snippet_css:
:root{
  --bg: #0C0A0F;
  --fg: #EAE6F0;
  --muted: #BDB6CC;
  --surface: #17121D;
  --border: #4A3A58;
  --accent: #E9C46A;
  --accent-fg: #1A1020;
  --accent-grad: linear-gradient(180deg,#F3D98C,#C9A34A);
  --radius: 2px;
  --radius-sm: 2px;
  --shadow: 0 26px 60px rgba(0,0,0,.72);
  --btn-shadow: 0 0 24px rgba(233,196,106,.22);
  --art-bg: radial-gradient(circle at 50% 34%,#5E0B1D 0 20%,#2A1638 21% 44%,#0C0A0F 45%);
  --media-bg: linear-gradient(180deg,#2A1638,#0C0A0F);
  --cta-bg: #1D1428;
  --input-bg: #17121D;
  --ok: #7FC79B;
  --warn: #E0795F;
  --font-display: 'Cormorant Garamond','Noto Serif TC',serif;
  --font-body: Lora,'Noto Serif TC',serif;
  --font-mono: ui-monospace,'SF Mono',Menlo,monospace;
  --focus-ring: var(--accent);
}

